import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Chatbot() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const navigate = useNavigate();

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMsg = { from: "user", text: input };
    setMessages((prev) => [...prev, userMsg]);

    const res = await fetch(
      (process.env.REACT_APP_API || "http://localhost:4000") + "/api/chatbot",
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ message: input }),
      }
    );

    const data = await res.json();

    const botMsg = {
      from: "bot",
      text: data.reply,
      buttons: data.buttons || [],
    };

    setMessages((prev) => [...prev, botMsg]);
    setInput("");
  };

  const handleButtonClick = (btn) => {
    // NEW FIX — supports navigation
    if (btn.startsWith("navigate:")) {
      const path = btn.replace("navigate:", "").trim();
      navigate(path);
      return;
    }
  };

  return (
    <div style={{ padding: "20px", width: "100%", maxWidth: "400px" }}>
      <div style={{ height: "400px", overflowY: "auto", border: "1px solid #ccc", padding: "10px" }}>
        {messages.map((msg, i) => (
          <div key={i} style={{ marginBottom: "15px" }}>
            <b>{msg.from === "user" ? "You:" : "Bot:"}</b> {msg.text}

            {msg.buttons && msg.buttons.length > 0 && (
              <div style={{ marginTop: "8px" }}>
                {msg.buttons.map((btn, idx) => (
                  <button
                    key={idx}
                    onClick={() => handleButtonClick(btn)}
                    style={{
                      marginRight: "10px",
                      padding: "5px 10px",
                      cursor: "pointer",
                    }}
                  >
                    {btn.replace("navigate:", "")}
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>

      <div style={{ marginTop: "10px" }}>
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          style={{ width: "75%", padding: "8px" }}
        />
        <button onClick={sendMessage} style={{ padding: "8px 15px" }}>
          Send
        </button>
      </div>
    </div>
  );
}
